package com.clavis.reader;
import android.app.*;import android.content.*;import android.content.res.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;
/** Theme/large-text regression checks. No library, notebook or playback records are changed. */
final class UiChecks {
 static int checks;static final ArrayList<String> failures=new ArrayList<>();
 static void check(boolean value,String message){checks++;if(!value)failures.add(message);}
 static double luminance(int color){double[] v={Color.red(color)/255.0,Color.green(color)/255.0,Color.blue(color)/255.0};for(int i=0;i<3;i++)v[i]=v[i]<=.04045?v[i]/12.92:Math.pow((v[i]+.055)/1.055,2.4);return v[0]*.2126+v[1]*.7152+v[2]*.0722;}
 static double contrast(int a,int b){double x=luminance(a),y=luminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
 static void walk(View v,ArrayList<View> out){out.add(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)walk(((ViewGroup)v).getChildAt(i),out);}
 static ArrayList<View> views(Activity a){ArrayList<View> out=new ArrayList<>();walk(a.getWindow().getDecorView(),out);return out;}
 static void noClippedText(View root,String label){ArrayList<View> out=new ArrayList<>();walk(root,out);for(View v:out)if(v instanceof TextView&&!(v instanceof PlayerButton)&&v.getVisibility()==View.VISIBLE){TextView t=(TextView)v;if(t.getText().length()==0||t.getLayout()==null)continue;check(t.getHeight()-t.getCompoundPaddingTop()-t.getCompoundPaddingBottom()+2>=t.getLayout().getLineBottom(t.getEllipsize()!=null?Math.min(t.getMaxLines(),t.getLayout().getLineCount())-1:t.getLayout().getLineCount()-1),label+": clipped height for "+t.getText());}}
 static void snapshot(Instrumentation i,Context c,String name)throws Exception{SystemClock.sleep(260);Bitmap bitmap=i.getUiAutomation().takeScreenshot();if(bitmap==null)return;java.io.File folder=new java.io.File(c.getExternalFilesDir(null),"ui-review");folder.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(folder,c.getResources().getConfiguration().fontScale+"-"+name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
 static void typedEntry(Instrumentation i,Context c,Activity journal,String mode)throws Exception{
  com.clavis.reader.notebook.PaperStore store=new com.clavis.reader.notebook.PaperStore(journal);
  com.clavis.reader.notebook.NotebookItem fixture=store.createNotebook("Clavis UI verification temporary",false);
  java.io.File folder=store.notebookFolder(fixture);TextEntryStore.write(folder,"Original entry");
  try{
   i.runOnMainSync(()->{try{for(java.lang.reflect.Method m:JournallingActivity.class.getDeclaredMethods())if(m.getName().startsWith("openNotebook")){m.setAccessible(true);m.invoke(journal,fixture);break;}}catch(Exception e){throw new RuntimeException(e);}});i.waitForIdleSync();
   i.runOnMainSync(()->{EditText editor=null;for(View v:views(journal))if(v instanceof EditText&&"Start your entry…".contentEquals(((EditText)v).getHint()))editor=(EditText)v;check(editor!=null,mode+": typed editor opens");if(editor==null)return;check(editor.getText().toString().equals("Original entry"),mode+": typed entry loads");editor.setText("Edited entry — café\nSecond paragraph");try{java.lang.reflect.Method save=JournallingActivity.class.getDeclaredMethod("saveTyped");save.setAccessible(true);check(Boolean.TRUE.equals(save.invoke(journal)),mode+": typed save succeeds");}catch(Exception e){throw new RuntimeException(e);}});
   check(TextEntryStore.read(folder).equals("Edited entry — café\nSecond paragraph"),mode+": typed edit survives save");snapshot(i,c,mode+"-text-entry");
   final EditText[] editorRef={null};i.runOnMainSync(()->{for(View v:views(journal))if(v instanceof EditText&&"Start your entry…".contentEquals(((EditText)v).getHint()))editorRef[0]=(EditText)v;if(editorRef[0]!=null){editorRef[0].requestFocus();((android.view.inputmethod.InputMethodManager)journal.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(editorRef[0],android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);}});SystemClock.sleep(500);snapshot(i,c,mode+"-text-keyboard");i.runOnMainSync(()->{if(Build.VERSION.SDK_INT>=30){View root=(View)journal.findViewById(R.id.cortex_notebookContent).getParent().getParent();int keyboard=root.getRootWindowInsets().getInsets(WindowInsets.Type.ime()).bottom;check(keyboard>0,mode+": keyboard opens");check(root.getPaddingBottom()>=keyboard,mode+": editor stays above keyboard");}if(editorRef[0]!=null)((android.view.inputmethod.InputMethodManager)journal.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(editorRef[0].getWindowToken(),0);});
  }finally{i.runOnMainSync(()->{try{java.lang.reflect.Method shelf=JournallingActivity.class.getDeclaredMethod("shelf");shelf.setAccessible(true);shelf.invoke(journal);}catch(Exception e){throw new RuntimeException(e);}});store.deleteNotebook(fixture.getId());}
 }
 static void handwriting(Instrumentation i,Context c,Activity journal,String mode)throws Exception{
  com.clavis.reader.notebook.PaperStore store=new com.clavis.reader.notebook.PaperStore(journal);com.clavis.reader.notebook.NotebookItem fixture=store.createNotebook("Clavis handwriting boundary check",true);
  try{
   i.runOnMainSync(()->{try{for(java.lang.reflect.Method m:JournallingActivity.class.getDeclaredMethods())if(m.getName().startsWith("openNotebook")){m.setAccessible(true);m.invoke(journal,fixture);break;}}catch(Exception e){throw new RuntimeException(e);}});i.waitForIdleSync();snapshot(i,c,mode+"-handwriting");
   i.runOnMainSync(()->{View content=journal.findViewById(R.id.cortex_notebookContent);View root=(View)content.getParent().getParent();WindowInsets insets=root.getRootWindowInsets();int status=insets.getInsets(WindowInsets.Type.statusBars()).top,nav=insets.getInsets(WindowInsets.Type.navigationBars()).bottom;int[] position=new int[2];View toolbar=journal.findViewById(R.id.cortex_toolbar);toolbar.getLocationOnScreen(position);check(root.getPaddingTop()>=status,mode+": handwriting receives status inset");check(root.getPaddingBottom()>=nav,mode+": handwriting receives navigation inset");check(position[1]>=status,mode+": handwriting toolbar below status bar");content.getLocationOnScreen(position);check(position[1]+content.getHeight()<=root.getHeight()-nav,mode+": handwriting viewport above navigation bar");check(journal.findViewById(R.id.cortex_paperHost)!=null,mode+": handwriting canvas open");});
  }finally{i.runOnMainSync(()->{try{java.lang.reflect.Method shelf=JournallingActivity.class.getDeclaredMethod("shelf");shelf.setAccessible(true);shelf.invoke(journal);}catch(Exception e){throw new RuntimeException(e);}});store.deleteNotebook(fixture.getId());}
 }
 static String run(Instrumentation i)throws Exception{
  checks=0;failures.clear();Context c=i.getTargetContext();java.io.File textFolder=new java.io.File(c.getCacheDir(),"text-entry-check");try{TextEntryStore.write(textFolder,"First line\\nSecond line — café");check(TextEntryStore.isText(textFolder),"typed entry mode persists");check(TextEntryStore.read(textFolder).equals("First line\\nSecond line — café"),"typed Unicode text round trip");TextEntryStore.write(textFolder,"Edited");check(TextEntryStore.read(textFolder).equals("Edited"),"typed edits persist");}finally{TextEntryStore.file(textFolder).delete();textFolder.delete();}android.content.SharedPreferences prefs=c.getSharedPreferences("appearance",0);boolean had=prefs.contains("dark"),saved=prefs.getBoolean("dark",true);Activity[] open={null};
  try{for(boolean dark:new boolean[]{false,true}){
   prefs.edit().putBoolean("dark",dark).commit();MainActivity main=(MainActivity)i.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));open[0]=main;i.waitForIdleSync();String mode=dark?"dark":"light";
   i.runOnMainSync(()->{check((main.getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==(dark?Configuration.UI_MODE_NIGHT_YES:Configuration.UI_MODE_NIGHT_NO),mode+": resources follow app preference");check(main.getColor(R.color.ink)==AppTheme.text,mode+": native and resource ink agree");check(contrast(AppTheme.text,AppTheme.surface)>=4.5,mode+": primary text contrast");check(contrast(AppTheme.muted,AppTheme.surface)>=4.5,mode+": secondary text contrast");check(contrast(AppTheme.muted,AppTheme.background)>=4.5,mode+": secondary canvas contrast");check(contrast(main.getColor(R.color.control_accent),AppTheme.surface)>=3,mode+": accent control contrast");noClippedText(main.mainFrame,mode+" home");SeekBar control=new SeekBar(main);AppTheme.tintProgress(control);int active=control.getThumbTintList().getColorForState(new int[]{android.R.attr.state_enabled},0);int disabled=control.getThumbTintList().getColorForState(new int[]{-android.R.attr.state_enabled},0);check(active==0xff8a72ad,mode+": identical accent");check(active!=disabled,mode+": disabled slider is distinct");EditText input=new EditText(main);AlertDialog d=new AppDialog.Builder(main).setTitle("Search books").setView(input).setPositiveButton("Search",null).setNegativeButton("Cancel",null).show();View parent=(View)input.getParent();check(parent.getPaddingLeft()>=main.dp(24),mode+": input gutter");check(input.getMinHeight()>=main.dp(48),mode+": input target");check(d.getButton(-1).getCurrentTextColor()==AppTheme.text,mode+": legible dialog action");d.dismiss();});
   snapshot(i,c,mode+"-home");for(String kind:new String[]{"Audio","Podcast"}){
    i.runOnMainSync(()->NowPlayingScreen.show(main,new Book("file:///ui-check-missing", "A long title for player layout verification",kind)));i.waitForIdleSync();
    i.runOnMainSync(()->{noClippedText(main.mainFrame,mode+" "+kind+" player");Rect frame=new Rect(),play=new Rect(),seek=new Rect();main.mainFrame.getGlobalVisibleRect(frame);main.playButton.getGlobalVisibleRect(play);main.seek.getGlobalVisibleRect(seek);check(play.height()>=main.dp(48),mode+": play button visible without scrolling");check(seek.height()>=main.dp(40),mode+": progress visible without scrolling");check(main.seek.getThumbTintList().getDefaultColor()==0xff8a72ad,mode+": player accent");});snapshot(i,c,mode+"-"+kind);
   }
   i.runOnMainSync(main::finish);i.waitForIdleSync();open[0]=null;
   Activity journal=i.startActivitySync(new Intent(c,JournallingActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));open[0]=journal;i.waitForIdleSync();snapshot(i,c,mode+"-journal");
   i.runOnMainSync(()->{check((journal.getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==(dark?Configuration.UI_MODE_NIGHT_YES:Configuration.UI_MODE_NIGHT_NO),mode+": notebook mode follows preference");check(journal.getColor(R.color.cortex_ink)==(dark?0xffedf2f2:0xff292b30),mode+": notebook ink matches");check(journal.getColor(R.color.cortex_card_background)==journal.getColor(R.color.card_background),mode+": notebook surface matches");View toolbar=journal.findViewById(R.id.cortex_toolbar);View root=(View)journal.findViewById(R.id.cortex_notebookContent).getParent().getParent();check(root.getPaddingTop()>0,mode+": journal respects status bar");check(root.getPaddingBottom()>0,mode+": journal respects navigation bar");check(toolbar.getHeight()-toolbar.getPaddingTop()<=Math.round(64*journal.getResources().getDisplayMetrics().density),mode+": notebook toolbar spacing");try{for(java.lang.reflect.Method m:JournallingActivity.class.getDeclaredMethods())if(m.getName().startsWith("createEntry")){m.setAccessible(true);AlertDialog d=(AlertDialog)m.invoke(journal);EditText input=d.findViewById(R.id.cortex_notebookName);check(d.getListView()!=null&&d.getListView().getCount()==2,mode+": Text and Write entry options");d.dismiss();break;}}catch(Exception e){throw new RuntimeException(e);}});typedEntry(i,c,journal,mode);handwriting(i,c,journal,mode);i.runOnMainSync(journal::finish);i.waitForIdleSync();open[0]=null;
  }}finally{if(open[0]!=null)i.runOnMainSync(open[0]::finish);if(had)prefs.edit().putBoolean("dark",saved).commit();else prefs.edit().remove("dark").commit();AppTheme.configureColors(c);}
  if(!failures.isEmpty())throw new AssertionError(checks+" UI checks; "+String.join("\n",failures));return checks+" UI checks passed at font scale "+c.getResources().getConfiguration().fontScale;
 }
}